// WP-20b bench (not a test): the spike's ascent / pad scenarios on the production binding (tests/vessel_physics_fixture.hpp) for any
// craft, with the timing split of the spike's `scaling` table. Used for the five-craft regression of STATUS.md WP-20b (the XL crafts
// are generated by core/spikes/jolt/tools/gen_xl_crafts.py; pass their path).
//
//   wp20b_bench ascent <craft name or .craft path>... [--ticks N] [--settle N] [--throttle T] [--no-aero] [--threads N]
//                                                     [--split] [--spike-damping] [--repeat N] [--loads none|tree|graph|auto]
// One line per craft: parts, bodies, constraints, tick mean / p95 and its parts (ms), altitude / speed at the end, pad drift.
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <string>
#include <vector>

#ifdef _WIN32
#define NOMINMAX
#define WIN32_LEAN_AND_MEAN
#include <windows.h>
#endif

#include "vessel_physics_fixture.hpp"

using namespace wp20b;

int main(int argc, char** argv) {
    if (argc < 3) {
        std::fprintf(stderr, "usage: wp20b_bench ascent <craft>... [--ticks N] [--settle N] [--throttle T] [--no-aero] [--threads N] [--split] [--spike-damping] [--repeat N]\n");
        return 2;
    }
    AscentConfig cfg;
    int repeat = 1;
    int samples = 0;  // print every n-th sample (0: none)
    unsigned long long affinity = 0;  // --affinity <hex mask>: pin to these logical CPUs at high priority (the spike's option)
    std::vector<std::string> crafts;
    for (int i = 2; i < argc; ++i) {
        const std::string a = argv[i];
        auto next = [&]() { return i + 1 < argc ? std::string(argv[++i]) : std::string(); };
        if (a == "--ticks") cfg.ticks = std::stoi(next());
        else if (a == "--settle") cfg.settleTicks = std::stoi(next());
        else if (a == "--throttle") cfg.throttle = std::stof(next());
        else if (a == "--no-aero") cfg.aero = false;
        else if (a == "--threads") cfg.threads = std::stoi(next());
        else if (a == "--split") cfg.policy = ClusterPolicy::SplitAtDecouplers;
        else if (a == "--spike-damping") cfg.angularDrag = AngularDragModel::ClusterMassAverage;
        else if (a == "--repeat") repeat = std::stoi(next());
        else if (a == "--drag") cfg.defaultAngularDrag = std::stof(next());
        else if (a == "--quads") cfg.terrainQuads = std::stoi(next());
        else if (a == "--fine-timing") cfg.fineTiming = true;
        else if (a == "--affinity") affinity = std::stoull(next(), nullptr, 16);
        else if (a == "--samples") samples = std::stoi(next());
        else if (a == "--loads") {  // WP-20c: the structural solve of AfterStep
            const std::string m = next();
            cfg.loads = m == "none" ? LoadSolve::None : m == "tree" ? LoadSolve::Tree : m == "graph" ? LoadSolve::Graph : LoadSolve::Auto;
        }
        else crafts.push_back(a);
    }
#ifdef _WIN32
    if (affinity != 0) {
        SetProcessAffinityMask(GetCurrentProcess(), static_cast<DWORD_PTR>(affinity));
        SetPriorityClass(GetCurrentProcess(), HIGH_PRIORITY_CLASS);
    }
#endif
    World w(true);
    std::printf("| craft | parts | bodies | constr. | tick mean | p95 | pipeline | ReadState+gravity | Flush | step | AfterStep | alt end (m) | v end | "
                "pad drift (m) | pad speed (m/s) |\n|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|\n");
    for (const std::string& c : crafts) {
        AscentResult best;
        for (int r = 0; r < repeat; ++r) {
            auto v = w.Craft(c);
            AscentResult res = RunAscent(w, *v, cfg);
            if (r == 0 || res.total.mean < best.total.mean) best = std::move(res);
        }
        std::string name = c;
        const size_t slash = name.find_last_of("/\\");
        if (slash != std::string::npos) name = name.substr(slash + 1);
        std::printf("| %s | %d | %d | %d | %.4f | %.4f | %.4f | %.4f | %.4f | %.4f | %.4f | %.2f | %.3f | %.3g | %.3g |%s\n", name.c_str(), best.parts,
                    best.bodies, best.constraints, best.total.mean, best.total.p95, best.pipeline.mean, best.precalc.mean, best.flush.mean, best.step.mean,
                    best.after.mean, best.altitudeEnd, best.speedEnd, best.maxDriftAfterSettle, best.maxSpeedAfterSettle, best.exploded ? " EXPLODED" : "");
        std::printf("    loads (WP-20c): %s solve %.4f ms/tick (inside AfterStep), %zu factorisations (last %.3f ms), max load / capacity %.4f (%s), %zu sub-joint breaks reported\n",
                    best.lastSolve == LoadSolve::Graph ? "graph" : best.lastSolve == LoadSolve::Tree ? "tree" : "no", best.tLoads, best.factorisations, best.factorMs,
                    best.maxLoadRatio, best.maxLoadJoint.c_str(), best.breaksReported);
        if (cfg.fineTiming) std::printf("    pipeline split (ms/tick): transforms+mass %.4f, aero setup %.4f, rb reads %.4f, UpdateAerodynamics %.4f, apply %.4f\n",
                    best.tTransforms, best.tAeroSetup, best.tRbRead, best.tAero, best.tApply);
        if (samples > 0)
            for (size_t k = 0; k < best.samples.size(); k += static_cast<size_t>(samples))
                std::printf("    t %7.2f  alt %10.3f  v %9.5f\n", best.samples[k].tick * cfg.dt, best.samples[k].altitude, best.samples[k].speed);
        std::fflush(stdout);
    }
    return 0;
}
